INSERT INTO arithmetic_tasks (subject, class_name, level, question, answer, image, explanation_of_the_answer)
VALUES
  ('arithmetic', '5–6 класс', 'Средний', 'Вычислите: 48 − 6 × 5 + 2.', '20', '/tasks/ar-m-01.jpg', 'Тема: порядок действий. Сначала умножение: 6 × 5 = 30. Затем слева направо: 48 − 30 = 18, 18 + 2 = 20.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Вычислите: 100 : (8 + 12) × 3.', '15', '/tasks/ar-m-02.jpg', 'Тема: порядок действий. Сначала скобки: 8 + 12 = 20. Затем 100 : 20 = 5, 5 × 3 = 15.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Запишите число: 5 миллионов 40 тысяч 7.', '5040007', '/tasks/ar-m-03.jpg', 'Тема: натуральные числа. 5 000 000 + 40 000 + 7. Сотни тысяч, сотни, десятки — нули: 5 040 007.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Сколько всего сотен в числе 3600?', '36', '/tasks/ar-m-04.jpg', 'Тема: натуральные числа. 3600 : 100 = 36. В числе 36 сотен.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Найдите наименьшее трёхзначное число, которое делится на 9.', '108', '/tasks/ar-m-05.jpg', 'Тема: признаки делимости. Сумма цифр должна делиться на 9. Наименьшее трёхзначное — 108 (1+0+8=9), 108 : 9 = 12.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Число 256 разделите на 2. Найдите частное.', '128', '/tasks/ar-m-06.jpg', 'Тема: признаки делимости. Число чётное, делится на 2. 256 : 2 = 128.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Найдите остаток от деления 100 на 7.', '2', '/tasks/ar-m-07.jpg', 'Тема: деление с остатком. 7 × 14 = 98, 100 − 98 = 2. Остаток 2.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Число 45 разделите на 9. Найдите частное.', '5', '/tasks/ar-m-08.jpg', 'Тема: признаки делимости. Сумма цифр 4+5=9 делится на 9. 45 : 9 = 5.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Вычислите: 1/2 + 1/6. Ответ запишите обыкновенной дробью.', '2/3', '/tasks/ar-m-09.jpg', 'Тема: сложение дробей. Общий знаменатель 6: 3/6 + 1/6 = 4/6. Сокращаем на 2: 2/3.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Вычислите: 5/6 − 1/3. Ответ запишите обыкновенной дробью.', '1/2', '/tasks/ar-m-10.jpg', 'Тема: вычитание дробей. 1/3 = 2/6. 5/6 − 2/6 = 3/6 = 1/2.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Найдите 3/4 от числа 80.', '60', '/tasks/ar-m-11.jpg', 'Тема: доля от числа. 80 : 4 = 20 (это 1/4). Затем 20 × 3 = 60.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Найдите 5/8 от числа 64.', '40', '/tasks/ar-m-12.jpg', 'Тема: доля от числа. 64 : 8 = 8. Затем 8 × 5 = 40.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Вычислите: 1,25 × 8. Ответ запишите целым числом или через запятую.', '10', '/tasks/ar-m-13.jpg', 'Тема: десятичные дроби. 1,25 × 8 = 10.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Вычислите: 7,2 : 0,9. Ответ запишите целым числом или через запятую.', '8', '/tasks/ar-m-14.jpg', 'Тема: десятичные дроби. Умножим делимое и делитель на 10: 72 : 9 = 8.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Найдите 15% от 80.', '12', '/tasks/ar-m-15.jpg', 'Тема: проценты. 1% от 80 — это 0,8. 15 × 0,8 = 12. Или 10% = 8, 5% = 4, сумма 12.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Число 50 увеличили на 20%. Какое число получили?', '60', '/tasks/ar-m-16.jpg', 'Тема: проценты. 20% от 50 — это 10. 50 + 10 = 60.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Найдите среднее арифметическое чисел 6, 9, 12 и 13.', '10', '/tasks/ar-m-17.jpg', 'Тема: среднее арифметическое. (6 + 9 + 12 + 13) : 4 = 40 : 4 = 10.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Найдите среднее арифметическое чисел 2, 8, 8, 6 и 6.', '6', '/tasks/ar-m-18.jpg', 'Тема: среднее арифметическое. (2 + 8 + 8 + 6 + 6) : 5 = 30 : 5 = 6.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Прямоугольник 12 см и 7 см. Найдите периметр.', '38', '/tasks/ar-m-19.jpg', 'Тема: периметр. (12 + 7) × 2 = 38 см.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Площадь квадрата 81 см². Найдите длину стороны.', '9', '/tasks/ar-m-20.jpg', 'Тема: площадь. Сторона — число, которое при умножении на себя даёт 81: 9 × 9 = 81.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Скорость 15 км/ч, время 3,5 часа. Найдите путь. Ответ через запятую.', '52,5', '/tasks/ar-m-21.jpg', 'Тема: движение. Путь = скорость × время: 15 × 3,5 = 52,5 км.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Два часа ехали со скоростью 40 км/ч, затем ещё 1 час со скоростью 20 км/ч. Какой весь путь?', '100', '/tasks/ar-m-22.jpg', 'Тема: движение. 40 × 2 = 80 км, плюс 20 × 1 = 20 км. Всего 100 км.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Купили 6 тетрадей по 15 рублей. Сколько заплатили?', '90', '/tasks/ar-m-23.jpg', 'Тема: задачи на покупку. 6 × 15 = 90 рублей.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Купили 3 ручки по 40 рублей и 2 карандаша по 25 рублей. Сколько заплатили?', '170', '/tasks/ar-m-24.jpg', 'Тема: задачи на покупку. 3 × 40 = 120, 2 × 25 = 50. Всего 170 рублей.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Сколько минут в 2 часах 45 минутах?', '165', '/tasks/ar-m-25.jpg', 'Тема: единицы времени. 2 часа = 120 минут, плюс 45: 165.'),
  ('arithmetic', '5–6 класс', 'Средний', '3,5 часа — это сколько минут?', '210', '/tasks/ar-m-26.jpg', 'Тема: единицы времени. 3 часа = 180 минут, половина часа = 30. Всего 210.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Округлите 3,46 до десятых. Ответ через запятую.', '3,5', '/tasks/ar-m-27.jpg', 'Тема: округление. Смотрим сотые: 6 ≥ 5, десятые увеличиваем: 3,5.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Округлите 847 до десятков.', '850', '/tasks/ar-m-28.jpg', 'Тема: округление. Цифра единиц 7 ≥ 5, десятки увеличиваем: 850.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Запишите смешанное число 1 2/3 как неправильную дробь, например 5/3.', '5/3', '/tasks/ar-m-29.jpg', 'Тема: смешанные числа. 1 × 3 + 2 = 5, знаменатель 3. Получается 5/3.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Сколько целых в дроби 17/4? Запишите только целое число.', '4', '/tasks/ar-m-30.jpg', 'Тема: смешанные числа. 17 : 4 = 4 (остаток 1), целых 4.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Найдите значение: −8 − 5. Если ответ отрицательный, поставьте минус, например -13.', '-13', '/tasks/ar-m-31.jpg', 'Тема: отрицательные числа (6 класс). От −8 ещё отнимаем 5: −13.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Найдите значение: −3 × 7.', '-21', '/tasks/ar-m-32.jpg', 'Тема: отрицательные числа (6 класс). Произведение отрицательного и положительного отрицательно: −21.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Число 35 разделили в отношении 2:5. Найдите меньшую часть.', '10', '/tasks/ar-m-33.jpg', 'Тема: отношение. Всего 2+5=7 частей. 35 : 7 = 5. Меньшая часть: 2 × 5 = 10.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Число 48 разделили в отношении 1:3. Найдите большую часть.', '36', '/tasks/ar-m-34.jpg', 'Тема: отношение. Всего 1+3=4 части. 48 : 4 = 12. Большая: 3 × 12 = 36.'),
  ('arithmetic', '5–6 класс', 'Средний', '3/5 числа равны 24. Найдите всё число.', '40', '/tasks/ar-m-35.jpg', 'Тема: найти целое по части. Одна пятая: 24 : 3 = 8. Всё число: 8 × 5 = 40.'),
  ('arithmetic', '5–6 класс', 'Средний', '15% числа равны 9. Найдите число.', '60', '/tasks/ar-m-36.jpg', 'Тема: найти целое по проценту. 1% — это 9 : 15 = 0,6. Всё число: 0,6 × 100 = 60.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Какая дробь больше: 2/5 или 3/8? Запишите большую дробь.', '2/5', '/tasks/ar-m-37.jpg', 'Тема: сравнение дробей. Приводим к 40: 16/40 и 15/40. Больше 2/5.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Какое число меньше: 0,65 или 7/10? Если десятичное — через запятую.', '0,65', '/tasks/ar-m-38.jpg', 'Тема: сравнение десятичных. 7/10 = 0,70. 0,65 меньше 0,70.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Равнобедренный треугольник со сторонами 10 см, 10 см и 6 см. Найдите периметр.', '26', '/tasks/ar-m-39.jpg', 'Тема: треугольник. 10 + 10 + 6 = 26 см.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Прямоугольный треугольник с катетами 6 см и 8 см. Найдите площадь.', '24', '/tasks/ar-m-40.jpg', 'Тема: площадь треугольника. Половина произведения катетов: (6 × 8) : 2 = 24 см².'),
  ('arithmetic', '5–6 класс', 'Средний', 'Найдите НОД чисел 24 и 36.', '12', '/tasks/ar-m-41.jpg', 'Тема: НОД. 24 = 2×2×2×3, 36 = 2×2×3×3. Общие множители 2×2×3 = 12.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Найдите НОК чисел 6 и 8.', '24', '/tasks/ar-m-42.jpg', 'Тема: НОК. 6 = 2×3, 8 = 2×2×2. Берём 2³ и 3: 8 × 3 = 24.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Переведите 2,5 км в метры.', '2500', '/tasks/ar-m-43.jpg', 'Тема: единицы длины. 1 км = 1000 м, значит 2,5 × 1000 = 2500 м.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Прямоугольный параллелепипед 4 см × 3 см × 5 см. Найдите объём.', '60', '/tasks/ar-m-44.jpg', 'Тема: объём. Объём = длина × ширина × высота: 4 × 3 × 5 = 60 см³.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Вычислите: 12,6 + 3,45. Ответ через запятую.', '16,05', '/tasks/ar-m-45.jpg', 'Тема: десятичные дроби. Выравниваем запятую: 12,60 + 3,45 = 16,05.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Вычислите: 0,8 × 0,5. Ответ через запятую.', '0,4', '/tasks/ar-m-46.jpg', 'Тема: десятичные дроби. 8 × 5 = 40, в множителях два знака после запятой: 0,40, то есть 0,4.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Вычислите: 2 × (3 + 7) − 4.', '16', '/tasks/ar-m-47.jpg', 'Тема: порядок действий. Сначала скобки: 3 + 7 = 10. Затем 2 × 10 = 20, 20 − 4 = 16.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Масштаб плана 1:100. На плане отрезок 5 см. Сколько это метров в реальности?', '5', '/tasks/ar-m-48.jpg', 'Тема: масштаб. 5 см × 100 = 500 см = 5 м.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Найдите 40% от 250.', '100', '/tasks/ar-m-49.jpg', 'Тема: проценты. 10% от 250 — это 25. 40% = 25 × 4 = 100.'),
  ('arithmetic', '5–6 класс', 'Средний', 'Два поезда едут навстречу: 60 км/ч и 40 км/ч. Расстояние 200 км. Через сколько часов встретятся?', '2', '/tasks/ar-m-50.jpg', 'Тема: движение навстречу. Скорости складываем: 60 + 40 = 100 км/ч. 200 : 100 = 2 часа.');
